UPDATE campus_report_job
job_name = #{jobName}, report_type = #{reportType}, generation_mode = #{generationMode}, scope_type = #{scopeType}, scope_keywords = #{scopeKeywords}, exclude_keywords = #{excludeKeywords}, platform_scope = #{platformScope}, risk_levels = #{riskLevels}, department_scope = #{departmentScope}, monitor_task_ids = #{monitorTaskIds}, analysis_profile = #{analysisProfile}, template_id = #{templateId}, event_id = #{eventId}, ai_user_prompt = #{aiUserPrompt}, period_rule = #{periodRule}, schedule_cron = #{scheduleCron}, output_format = #{outputFormat}, job_status = #{jobStatus}, last_run_time = #{lastRunTime}, next_run_time = #{nextRunTime}, next_run_time = NULL, schedule_lock_until = NULL, schedule_lock_until = #{scheduleLockUntil}, reviewer_user_id = #{reviewerUserId}, description = #{description}, update_user_id = #{updateUserId}
WHERE report_job_id = #{reportJobId} AND deleted = 0

UPDATE campus_report_job
SET schedule_lock_until = NULL,
    update_user_id = #{updateUserId}
WHERE report_job_id = #{reportJobId}
  AND deleted = 0

UPDATE campus_report_job
SET schedule_lock_until = #{lockUntil},
    update_user_id = #{updateUserId}
WHERE report_job_id = #{reportJobId}
  AND deleted = 0
  AND (schedule_lock_until IS NULL OR schedule_lock_until <= #{now})

UPDATE campus_report_job
SET deleted = 1,
    update_user_id = #{updateUserId}
WHERE report_job_id = #{reportJobId}
  AND deleted = 0

